// CRITICAL FIX: Real shared-secret validation (Phase 2B)
// Token is stored in n8n env/credential, never in workflow JSON, never logged
// Headers: X-N8N-Token, X-Callback-Token, Authorization Bearer
// Fail-closed: reject missing/invalid, accept only exact match

const headers = $input.first().json.headers || $json.headers || {};
const body = $input.first().json.body || $json.body || $json;

// Read expected secret from n8n environment/credential storage (not hardcoded, not logged)
const expected = ($env.N8N_WEBHOOK_TOKEN || $env.N8N_CALLBACK_TOKEN || '').trim();

if (!expected) {
  throw new Error('Server misconfigured: shared token not set in n8n env (N8N_WEBHOOK_TOKEN/N8N_CALLBACK_TOKEN)');
}

// Extract supplied token from supported headers
const authHeader = (headers['authorization'] || '').trim();
const bearer = authHeader.toLowerCase().startsWith('bearer ') ? authHeader.slice(7).trim() : '';
const supplied = (headers['x-n8n-token'] || headers['x-callback-token'] || bearer || '').trim();

// Reject missing token
if (!supplied) {
  throw new Error('Missing authentication token - X-N8N-Token required');
}

// Accept only exact match, never log token values
if (supplied !== expected) {
  throw new Error('Invalid authentication token');
}

// Payload schema validation (security: no full_log forwarding)
const required = ['alert_id', 'severity', 'score', 'decision', 'rule', 'recurrence', 'iocs', 'enrichment', 'investigation_links'];
for (const field of required) {
  if (!(field in body)) {
    throw new Error(`Payload validation failed: missing ${field}`);
  }
}

// Security check: ensure no full_log in payload (defense in depth)
const payloadStr = JSON.stringify(body).toLowerCase();
if (payloadStr.includes('full_log')) {
  throw new Error('Security violation: payload must not contain full_log');
}

// Enrich with routing metadata
return {
  json: {
    ...body,
    _router: {
      validated: true,
      received_at: new Date().toISOString(),
      is_high_severity: ['high', 'critical'].includes(body.severity),
      is_escalation: body.severity === 'critical' || (body.decision && body.decision.severity === 'SEV1')
    }
  }
};
